# -*- coding: utf-8 -*-
# (speaker, italian, korean); speaker None => stage direction, "#" => scene heading (neither is a turn)
F, L, R, S, M, MA, C = "Filippo", "Lorenzo", "Renzo", "Simone", "Matteo", "Marisa", "Chiara"
D = [
("#", "Scena 1 — Venerdì 14 marzo, ore 8. L'ufficio di Filippo.", "장면 1 — 3월 14일 금요일 오전 8시. 필리포의 사무실."),
(None, "Sulla scrivania, una cartella rossa, una tazza di caffè già fredda e la foto di Giulia a sei anni con una borsa più grande di lei. Lorenzo entra con un portatile sotto il braccio e le occhiaie di chi ha dormito poco.", "책상 위에 빨간 서류철, 이미 식은 커피 한 잔, 자기보다 큰 가방을 든 여섯 살 줄리아의 사진. 로렌초가 노트북을 옆구리에 끼고 들어온다. 잠을 덜 잔 사람의 다크서클."),
(L, "Ho chiuso i conti del marchio alle due di stanotte. Vuoi la versione breve o quella vera?", "어젯밤 2시에 브랜드 숫자를 마감했어. 짧은 버전으로 들을래, 진짜 버전으로 들을래?"),
(F, "Quella vera. Quella breve me la racconto da solo, di notte.", "진짜 버전. 짧은 건 밤에 혼자 나한테 들려주고 있어."),
(L, "Ordini dopo il MIPEL. Seul: sessanta borse, circa diciannovemila ottocento euro franco fabbrica.", "MIPEL 이후 주문. 서울, 가방 60개, 공장 출고가 기준 약 1만 9,800유로."),
(F, "Questo lo so. E poi?", "그건 알아. 그다음은?"),
(L, "Poi due negozi italiani e uno tedesco. Una boutique a Bologna, dodici pezzi. Una a Verona, otto. E un negozio di Monaco di Baviera, quindici.", "그리고 이탈리아 매장 두 곳, 독일 한 곳. 볼로냐 부티크 12개, 베로나 8개. 뮌헨 매장 15개."),
(F, "Trentacinque borse. Con Seul, novantacinque.", "35개. 서울까지 합치면 95개."),
(L, "E il sito: ventitré ordini dal lancio. Dopo il video dell'influencer, cinquecentomila visite.", "그리고 사이트. 오픈 이후 주문 23건. 인플루언서 영상 뒤로 방문은 50만."),
(F, "Cinquecentomila visite e ventitré ordini. Se lo dico così in banca, mi ridono in faccia.", "방문 50만에 주문 23건. 은행에서 이렇게 말하면 대놓고 웃을 거야."),
(L, "In banca non lo dici così. Dici: conversione bassa, sito in rifacimento, prima versione inglese online da martedì.", "은행에선 그렇게 말 안 하지. 이렇게 말해. 전환율 낮음, 사이트 개편 중, 영어판 첫 버전은 화요일부터 운영."),
(F, "E le spese?", "지출은?"),
(L, "Dal tetto di centocinquanta: fiera e trasferte, diciotto e cinque, stand compreso. Comunicazione, tra Nora e le foto, sette e cinque. Il sito, due e otto. I primi pellami di Bini, cinque.", "15만 상한에서. 박람회랑 출장 1만 8,500, 부스 포함. 홍보는 노라랑 사진 합쳐서 7,500. 사이트 2,800. 비니의 첫 가죽 5,000."),
(F, "Totale?", "합계는?"),
(L, "Trentatré e otto. Restano centosedici e due. Ma due mesi di Nora sono già impegnati: altri sette.", "3만 3,800. 남은 건 11만 6,200. 그런데 노라 두 달 치가 이미 잡혀 있어. 7,000 더."),
(F, "Quindi, davvero, centonove.", "그러니까 실제로는 10만 9,000."),
(L, "Centonove. E abbiamo incassato... niente. Seul paga a trenta giorni dalla consegna. Monaco a sessanta. Bologna e Verona a fine mese.", "10만 9,000. 그리고 들어온 돈은… 없어. 서울은 납품 후 30일, 뮌헨은 60일. 볼로냐랑 베로나는 월말 결제."),
(F, "Cioè i primi soldi veri li vediamo a fine maggio.", "그러니까 진짜 돈은 5월 말에야 보는 거네."),
(L, "Quando avremo consegnato Seul e incassato la prima fattura, sì. Se tutto va bene.", "서울 납품을 마치고 첫 송장 대금을 받고 나면, 그렇지. 다 잘 풀린다면."),
(F, "E il piano per la banca? Scade il trentuno.", "은행 사업계획서는? 31일 마감인데."),
(L, "La parte Maison è pronta. La parte marchio, per ora, è un foglio pieno di «se».", "메종 부분은 준비됐어. 브랜드 부분은 지금으로선 '만약'으로 가득한 종이 한 장이고."),
(F, "La dottoressa Ferretti odia i «se». Me l'ha detto con un sorriso, ma l'ha detto.", "페레티 담당은 '만약'을 싫어해. 웃으면서 말하긴 했지만, 말은 했어."),
(L, "Allora trasformiamoli in date. Che cosa succede, e quando.", "그럼 '만약'을 날짜로 바꾸자. 무슨 일이 언제 일어나는지."),
(F, "Le date le so io. Il ventotto, il prototipo per Parigi. Il diciotto aprile, la spedizione per Seul. E il trenta aprile...", "날짜는 내가 알지. 28일, 파리 시제품. 4월 18일, 서울 선적. 그리고 4월 30일…"),
(L, "Il trenta aprile scade l'accordo con le RSU.", "4월 30일엔 노조 합의가 끝나지."),
(F, "Sia l'accordo sia la mia pazienza. Magari avessimo trenta giorni in più.", "합의도, 내 인내심도. 30일만 더 있으면 좋겠다."),
(L, "Ti posso dare un consiglio da ragioniere?", "회계쟁이로서 조언 하나 해도 될까?"),
(F, "Da ragioniere sì. Da amico, oggi no.", "회계쟁이로선 좋아. 친구로선 오늘은 사양할게."),
(L, "Nel piano, il marchio non metterlo come una speranza. Mettilo come un esperimento: un costo massimo e una data di verifica. Le banche non amano i sogni, ma gli esperimenti li capiscono.", "계획서에 브랜드를 희망으로 넣지 마. 실험으로 넣어. 최대 비용 하나, 점검 날짜 하나. 은행은 꿈은 싫어하지만 실험은 이해하거든."),
(F, "Un esperimento con il tetto a centocinquanta e la verifica a fine aprile. Scrivilo così.", "상한 15만에 점검은 4월 말인 실험. 그렇게 써."),

("#", "Scena 2 — Ore 10.30. Il laboratorio, il banco di Renzo.", "장면 2 — 오전 10시 30분. 공방, 렌초의 작업대."),
(None, "Sul banco, il prototipo per la Maison Varenne: una borsa rigida con un soffietto curvo. Simone tiene una lampada da lavoro puntata sulla cucitura. Renzo ha gli occhiali sulla punta del naso.", "작업대 위에 메종 바렌의 시제품이 있다. 곡선 옆판(소피에토)이 달린 각진 가방. 시모네가 작업등을 박음질에 비추고 있다. 렌초는 안경을 코끝에 걸쳤다."),
(F, "Renzo, mi dica la verità. Il prototipo per Parigi è pronto per fine mese?", "렌초, 솔직히 말해 주세요. 파리 시제품, 월말까지 될까요?"),
(R, "La verità è che è una borsa cattiva. Il soffietto curvo non perdona. Ogni volta che lo monto, la pelle tira di un millimetro.", "솔직히 말하면 고약한 가방이에요. 곡선 옆판은 용서가 없어요. 조립할 때마다 가죽이 1밀리미터씩 당겨요."),
(F, "Un millimetro.", "1밀리미터."),
(R, "Un millimetro su una borsa da tremila euro è una ruga in faccia. Hélène la vede da Parigi.", "3천 유로짜리 가방에 1밀리미터면 얼굴에 난 주름이에요. 엘렌은 파리에서도 그걸 봐요."),
(F, "Quanto tempo le serve?", "시간이 얼마나 필요하세요?"),
(R, "Altri tre giorni. E le mani di Simone tutti i pomeriggi.", "사흘 더. 그리고 오후마다 시모네의 손."),
(S, "Io ci sono, signor Filippo.", "저 할 수 있어요, 필리포 사장님."),
(F, "Simone, qui si dà del tu. Anche al direttore.", "시모네, 여기선 다들 말 편하게 해. 사장한테도."),
(S, "Sì... ci sono, Filippo.", "네… 할 수 있어요, 필리포."),
(R, "Vede? Sta imparando. Il soffietto, invece, ancora no.", "보세요. 배우고 있잖아요. 옆판은 아직 아니지만."),
(None, "Matteo arriva di corsa, un foglio di produzione in mano.", "마테오가 생산 일정표를 들고 뛰어온다."),
(M, "Filippo, ti cercavo. Le sessanta per Seul: dobbiamo cominciare il taglio lunedì, se vogliamo spedire il diciotto aprile.", "형, 찾고 있었어. 서울용 60개, 4월 18일에 선적하려면 월요일엔 재단을 시작해야 해."),
(F, "Lunedì Simone è con Renzo.", "월요일엔 시모네가 렌초랑 있어."),
(M, "Allora prendo le ragazze della linea Maison. Quelle che si sono offerte volontarie.", "그럼 메종 라인 사람들을 데려갈게. 자원한 사람들."),
(F, "Quante si sono offerte, alla fine?", "결국 몇 명이 자원했어?"),
(M, "Otto. Con l'accordo di gennaio il passaggio è volontario, e sono venute da sole.", "여덟 명. 1월 합의대로 이동은 자원이고, 다들 스스로 왔어."),
(R, "Otto brave. Sei le conosco da quando erano apprendiste come lui.", "여덟 명 다 솜씨가 좋아요. 여섯은 쟤처럼 견습생일 때부터 알았죠."),
(F, "E se tolgo otto persone alla Maison proprio mentre facciamo il prototipo?", "시제품 만드는 이 와중에 메종에서 여덟 명을 빼면?"),
(M, "Non le togli. La Maison ci dà il trenta per cento di lavoro in meno, Filippo. Quelle otto, senza Seul, starebbero a guardare.", "빼는 게 아니야. 메종 일이 30% 줄었잖아, 형. 그 여덟 명, 서울이 없으면 그냥 구경만 하고 있을 거야."),
(F, "(silenzio) Hai ragione. Ma il prototipo ha la precedenza. Se Parigi ci boccia questo, le sessanta borse per Seul diventano un hobby.", "(침묵) 네 말이 맞아. 하지만 시제품이 우선이야. 파리가 이걸 퇴짜 놓으면, 서울용 60개는 취미가 되는 거야."),
(M, "Non dire «hobby». Lo sai che effetto fa a Chiara.", "'취미'라는 말 하지 마. 누나한테 그게 어떤 말인지 알잖아."),
(F, "Lo so. Lo dico a te, non a lei.", "알아. 그러니까 너한테 하는 거지, 걔한테가 아니라."),
(M, "E se lo dici a me, prima o poi lo dici anche a tavola. Ti conosco.", "나한테 하는 말은 언젠가 식탁에서도 하게 돼. 형을 알거든."),
(F, "(irrigidito) A tavola dico quello che decidiamo. Non quello che temo.", "(굳은 얼굴로) 식탁에선 우리가 정한 걸 말해. 내가 두려워하는 게 아니라."),
(R, "Ragazzi. Il prototipo lo consegno il ventotto. E le ragazze le mandi pure a Matteo. Le mani non sono una coperta corta: se le sai organizzare, coprono tutto.", "얘들아. 시제품은 28일에 넘긴다. 그리고 그 사람들은 마테오한테 보내세요. 손은 짧은 이불이 아니에요. 잘 짜기만 하면 다 덮어요."),
(F, "Il ventotto. Me lo segno.", "28일. 적어 둘게요."),
(R, "Se lo segni. Ma non me lo chieda ogni mattina.", "적으세요. 대신 매일 아침 묻지는 마시고요."),
(S, "Lo chiede a me, poi. Io glielo dico solo se va bene.", "그럼 저한테 물으세요. 잘될 때만 말씀드릴게요."),
(F, "(quasi ride) Ecco un altro che sta imparando troppo in fretta.", "(웃을 뻔하며) 또 하나가 너무 빨리 배우고 있네."),
(M, "Allora siamo d'accordo: lunedì le otto tagliano per Seul, Simone resta con Renzo.", "그럼 합의한 거지. 월요일에 여덟 명은 서울용 재단, 시모네는 렌초 옆에."),
(F, "D'accordo. Ma se il ventotto il prototipo non c'è, le otto tornano alla Maison. Tutte e otto.", "좋아. 하지만 28일에 시제품이 안 나오면 여덟 명 모두 메종으로 돌아간다."),
(R, "Ci sarà. Le borse cattive, alla fine, si arrendono anche loro.", "나와요. 고약한 가방도 결국엔 항복하거든요."),

("#", "Scena 3 — Ore 14.30. L'ufficio di Filippo.", "장면 3 — 오후 2시 30분. 필리포의 사무실."),
(None, "Qualcuno bussa due colpi secchi. È Marisa, con il grembiule ancora addosso e il metro da sarta al collo.", "누군가 짧게 두 번 노크한다. 앞치마를 두른 채 줄자를 목에 건 마리사다."),
(MA, "Posso? Ho dieci minuti, poi rientro in linea.", "들어가도 돼? 10분 있어. 그다음엔 라인으로 돌아가야 해."),
(F, "Entra, Marisa. Siediti.", "들어와요, 마리사. 앉아요."),
(MA, "Non mi siedo, che poi non mi rialzo. Ti dico una cosa sola: in mensa non si parla d'altro.", "안 앉아. 앉으면 못 일어나. 한마디만 할게. 식당에서 다들 그 얘기뿐이야."),
(F, "Dell'articolo?", "기사 얘기?"),
(MA, "Ma quale articolo. Del trenta aprile. L'accordo scade e le ragazze vogliono sapere che cosa succede dopo.", "기사는 무슨. 4월 30일 얘기지. 합의가 끝나는데 다들 그다음에 어떻게 되는지 알고 싶어 해."),
(F, "Dopo dipende dagli ordini. Lo sai.", "그다음은 주문에 달렸죠. 알잖아요."),
(MA, "Lo so. Ma loro hanno visto le borse nuove sul telefono, con le cinquecentomila visite, e pensano che siamo ricchi.", "알지. 그런데 다들 휴대폰으로 새 가방이랑 방문 50만을 보고는 우리가 부자가 된 줄 알아."),
(F, "Cinquecentomila visite. Ventitré ordini.", "방문 50만. 주문 23건."),
(MA, "Ecco, diglielo così. Meglio una verità brutta che delle voci belle.", "그래, 그렇게 말해. 예쁜 소문보다 못생긴 진실이 낫지."),
(F, "La verità è questa: la Maison ci dà il settanta per cento del lavoro di prima. Il marchio, per ora, ne dà a otto persone.", "진실은 이거예요. 메종 일은 예전의 70%. 브랜드는 지금으로선 여덟 명한테 일을 줘요."),
(MA, "E le altre trenta e passa?", "그럼 나머지 서른 명 남짓은?"),
(F, "Fino al trenta aprile nessuno resta a casa. Dopo... ci rivediamo a fine aprile, come abbiamo scritto. Con i numeri.", "4월 30일까지는 아무도 집에 있지 않아요. 그다음은… 적어 둔 대로 4월 말에 다시 만나요. 숫자를 들고."),
(MA, "Se me lo dicevi a gennaio, che finiva così stretta, le ragazze dormivano più tranquille.", "이렇게 빠듯하게 끝날 거라고 1월에 말해 줬으면, 다들 좀 더 편히 잤을 거야."),
(F, "A gennaio non lo sapevo nemmeno io.", "1월엔 나도 몰랐어요."),
(MA, "Lo so. Per questo te lo dico adesso: le cose, dille prima. Anche quelle che non sai ancora.", "알아. 그래서 지금 말하는 거야. 일은 먼저 말해. 아직 모르는 것까지도."),
(F, "Anche quelle che non so?", "모르는 것까지요?"),
(MA, "Soprattutto quelle. «Non lo so ancora» è una frase che si può dire. Il silenzio, no.", "특히 그거. '아직 모르겠다'는 말할 수 있는 문장이야. 침묵은 안 돼."),
(F, "(annuisce) «Non lo so ancora.» Me lo segno.", "(고개를 끄덕이며) '아직 모르겠다.' 적어 둘게요."),
(MA, "Con i numeri, va bene. Ma quel giorno voglio vedere anche la faccia di tua madre.", "숫자 들고, 좋아. 그런데 그날 네 어머니 얼굴도 보고 싶어."),
(F, "Ci sarà. E ci sarà anche la mia.", "오실 거예요. 내 얼굴도 있을 거고."),
(MA, "Le otto che sono andate con tuo fratello... sono contente, sai? Dicono che nelle borse nuove si vede chi le fa.", "네 동생한테 간 여덟 명… 좋아하는 거 알아? 새 가방에는 누가 만들었는지가 보인대."),
(F, "Davvero?", "정말요?"),
(MA, "Davvero. Una mi ha detto: «Per la Maison facciamo trecento borse uguali. Per i Corsini ne facciamo dieci, e ognuna ha un nome.»", "정말. 한 사람이 그러더라. '메종에는 똑같은 가방 300개를 만들고, 코르시니에는 열 개를 만드는데 하나하나 이름이 있어.'"),
(F, "(pausa) Questo non me lo dice mai nessuno.", "(잠시) 그런 말은 아무도 나한테 안 해 줘요."),
(MA, "Perché tu stai quassù con i fogli. Scendi in laboratorio, ogni tanto. Tuo padre scendeva tutti i giorni alle undici.", "네가 여기 위층에서 서류만 보고 있으니까. 가끔 공방에 내려와. 네 아버지는 매일 11시에 내려왔어."),
(F, "Alle undici. Me lo ricordo. Portava le paste il venerdì.", "11시. 기억나요. 금요일엔 페이스트리를 사 오셨죠."),
(MA, "Oggi è venerdì.", "오늘 금요일이야."),
(F, "(si alza, prende la giacca) Allora scendo. Che paste vogliono, le ragazze?", "(일어나 재킷을 집으며) 그럼 내려가야겠네요. 다들 무슨 페이스트리 좋아해요?"),
(MA, "Bomboloni. E non chiedere a me quanti: contale tu, le teste. Così le guardi in faccia.", "봄볼로니. 몇 개냐고 나한테 묻지 마. 머릿수는 네가 세. 그래야 얼굴을 보지."),

("#", "Scena 4 — Ore 18.30. L'ufficio di Filippo, porta chiusa.", "장면 4 — 오후 6시 30분. 필리포의 사무실, 문 닫힘."),
(None, "Sul tavolo, un vassoio con due bomboloni avanzati. Filippo, Matteo, Chiara e Lorenzo. Fuori, il rumore delle macchine che si spengono una dopo l'altra.", "탁자 위에 남은 봄볼로니 두 개가 담긴 쟁반. 필리포, 마테오, 키아라, 로렌초. 밖에서는 기계들이 하나씩 꺼지는 소리."),
(F, "Chiudete la porta. Lorenzo, i numeri. Tutti e quattro devono sentire la stessa cosa.", "문 닫아. 로렌초, 숫자. 네 사람 모두 같은 얘기를 들어야 해."),
(L, "Novantacinque borse ordinate, ventitré ordini dal sito. Spesi trentatré e otto, impegnati altri sette. Restano centonove. Incassato, zero.", "가방 주문 95개, 사이트 주문 23건. 지출 3만 3,800, 추가 약정 7,000. 남은 건 10만 9,000. 입금, 0."),
(C, "Zero per ora. Seul paga a trenta giorni.", "지금은 0이지. 서울은 30일 뒤에 줘."),
(F, "Lo so, Chiara. Non è un processo. È una fotografia.", "알아, 키아라. 재판이 아니야. 사진 한 장일 뿐이야."),
(M, "E che cosa ci vedi, in questa fotografia?", "그럼 그 사진에서 뭐가 보여?"),
(F, "Ci vedo che il trenta aprile scadono tre cose insieme: l'accordo con le RSU, la pazienza della banca e la mia.", "4월 30일에 세 가지가 한꺼번에 끝난다는 게 보여. 노조 합의, 은행의 인내심, 그리고 내 인내심."),
(M, "Filippo...", "형…"),
(F, "Fammi finire. Non mi aspetto che diventiamo ricchi in sei settimane. Ma a fine aprile voglio vedere risultati. Non visite, non cuori sotto le foto. Ordini pagati, o almeno confermati per iscritto, oltre a Seul.", "끝까지 들어. 6주 만에 부자가 되길 바라진 않아. 하지만 4월 말엔 결과를 보고 싶어. 방문 수도, 사진 밑 하트도 아니고. 서울 말고, 돈이 들어왔거나 적어도 서면으로 확정된 주문."),
(C, "E se non li vedi?", "못 보면?"),
(F, "Se a fine aprile non vedo risultati, il budget del marchio lo congelo. Non lo chiudo. Lo congelo.", "4월 말에 결과가 안 보이면 브랜드 예산을 동결할 거야. 없애는 게 아니야. 동결."),
(C, "Come nel duemilaquindici.", "2015년처럼."),
(F, "No. Nel duemilaquindici l'ho chiusa senza dirtelo prima. Stavolta te lo dico sei settimane prima. È diverso.", "아니. 2015년엔 너한테 미리 말도 안 하고 접었지. 이번엔 6주 전에 말하는 거야. 그건 달라."),
(M, "Sei settimane. In sei settimane spediamo Seul, finiamo il sito e rispondiamo a tutti quelli che hanno scritto.", "6주. 6주면 서울 선적하고, 사이트 마무리하고, 연락 온 사람들한테 다 답할 수 있어."),
(L, "Anche a Tokyo?", "도쿄도?"),
(M, "Il catalogo è partito martedì. Il signor Watanabe ha risposto con due righe: «Ricevuto. Ci vedremo in primavera.» Niente di più.", "카탈로그는 화요일에 보냈어. 와타나베 씨는 두 줄로 답했어. '받았습니다. 봄에 뵙겠습니다.' 그게 다야."),
(F, "Due righe non si mettono in un bilancio.", "두 줄은 재무제표에 못 넣어."),
(C, "No. Ma questa sì. (posa un foglio sul tavolo) La Collina. Il prototipo sarà pronto mercoledì.", "그래. 하지만 이건 넣을 수 있어. (종이를 탁자에 내려놓으며) 라 콜리나. 시제품은 수요일에 나와."),
(None, "Filippo guarda a lungo il disegno: una sola linea curva, una piega senza cucitura sopra. Stamattina, sulla scrivania di Chiara, c'era un caffè con due zuccheri.", "필리포가 오래 그림을 본다. 곡선 하나, 위에 박음질 없는 접힘 하나. 오늘 아침 키아라의 작업대 위에는 설탕 두 개를 넣은 커피가 놓여 있었다."),
(F, "È diversa.", "다르네."),
(C, "È mia.", "내 거야."),
(F, "Sì. Si vede.", "그래. 보여."),
(L, "Quanto costa farla?", "만드는 데 얼마 들어?"),
(C, "Meno della Scandicci. Una cucitura in meno, una piega in più. Renzo dice due ore di banco, non due e mezza.", "스칸디치보다 적게. 박음질 하나 빼고, 접힘 하나 더하고. 렌초 말로는 작업대에서 두 시간 반이 아니라 두 시간."),
(L, "Due ore invece di due e mezza. Su cento borse sono cinquanta ore di laboratorio risparmiate.", "두 시간 반 대신 두 시간. 가방 100개면 공방 시간 50시간이 절약돼."),
(M, "E con lo stesso cuoio di Bini. Nessun materiale nuovo da comprare.", "가죽도 비니 걸 그대로 써. 새로 살 재료가 없어."),
(F, "E chi la compra, la Collina? Seul?", "그럼 라 콜리나는 누가 사? 서울?"),
(M, "A Seul la portiamo come pezzo unico per il pop-up. Se piace, la prima produzione è per maggio.", "서울 팝업엔 단품으로 가져가. 반응이 좋으면 첫 생산은 5월."),
(C, "E se a Seul non piace, la porto io in giro per Milano. A piedi, negozio per negozio.", "서울에서 안 먹히면 내가 들고 밀라노를 돌게. 걸어서, 매장마다."),
(F, "Va bene. Il congelamento resta sul tavolo. Ma anche la Collina resta sul tavolo.", "좋아. 동결은 탁자 위에 그대로 있어. 하지만 라 콜리나도 탁자 위에 있는 거야."),
(M, "Martedì vado a Milano, in uno showroom. Se ci prendono in vetrina per la stagione, è un risultato.", "화요일에 밀라노 쇼룸에 가. 이번 시즌 진열에 넣어 주면 그게 결과야."),
(F, "Martedì? Vengo anch'io. In macchina. Così parliamo.", "화요일? 나도 갈래. 차로. 그래야 얘기도 하지."),
(M, "In macchina. Tre ore di autostrada, io e te.", "차로. 고속도로 세 시간, 형이랑 나랑."),
(C, "(ride per la prima volta in tutta la settimana) Portatevi i caschi.", "(이번 주 들어 처음으로 웃으며) 헬멧 챙겨."),
]

